import XCTest

final class BlueskyUITests: XCTestCase {
    func testRecon() throws {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.launch()
        Thread.sleep(forTimeInterval: 5)
        print("HIERARCHY_START")
        print(app.debugDescription)
        print("HIERARCHY_END")
    }
}

import XCTest

final class BlueskyUITests: XCTestCase {
    func testRecon() throws {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.launch()
        Thread.sleep(forTimeInterval: 5)
        print("HIERARCHY_START")
