        print("HIERARCHY_END")
    }
}

import XCTest

final class BlueskyUITests: XCTestCase {
    func testRecon() throws {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let bluesky = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")

        let openBtn = springboard.alerts.buttons["Open"]
        if openBtn.waitForExistence(timeout: 5) {
            openBtn.tap()
        }
        Thread.sleep(forTimeInterval: 4)
        print("BSKY_STATE_START")
        for (i, el) in bluesky.descendants(matching: .any).allElementsBoundByIndex.enumerated() {
            print("EL \(i) type=\(el.elementType.rawValue) label=\(el.label) id=\(el.identifier) frame=\(el.frame)")
        }
        print("BSKY_STATE_END")
    }
}

import XCTest

final class BlueskyUITests: XCTestCase {
    func testSearchPeople() throws {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let bluesky = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        bluesky.activate()

        let openBtn = springboard.alerts.buttons["Open"]
        if openBtn.waitForExistence(timeout: 2) {
            openBtn.tap()
            Thread.sleep(forTimeInterval: 3)
        }

        let field = bluesky.textFields["Search"]
        if !field.waitForExistence(timeout: 10) {
            bluesky.buttons["Search"].firstMatch.tap()
            XCTAssertTrue(field.waitForExistence(timeout: 10))
        }
        if (field.value as? String) != "test" {
            field.tap()
            field.typeText("test")
            let kbSearch = springboard.keyboards.buttons["Search"]
            if kbSearch.waitForExistence(timeout: 3) {
                kbSearch.tap()
            } else {
                field.typeText("\n")
            }
            Thread.sleep(forTimeInterval: 2)
        }

        let people = bluesky.otherElements.matching(NSPredicate(format: "label == 'People'")).firstMatch
        XCTAssertTrue(people.waitForExistence(timeout: 10))
        people.tap()
        Thread.sleep(forTimeInterval: 3)
    }
}

